pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 || amount == 0);
        vm.prank(address(this));
        c.OpenToThePublic();
        bool before = c.hasPlayerWagered(address(this));
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);
        bool after = c.hasPlayerWagered(address(this));
        assertTrue(true);
    }
}

