    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this) && caller != address(0));

        uint256 betLimitBefore = c.currentBetLimit();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.AdjustBetAmounts.selector, amount));
        uint256 betLimitAfter = c.currentBetLimit();

        if (caller == address(this)) {
            assertTrue(success && betLimitAfter == amount);
        } else {
            assertTrue(!success || betLimitAfter == betLimitBefore);
        }
    }
}

