pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit) public {
        // Ensure openToPublic is true for wager/play functions to work (though not needed for this property)
        c.OpenToThePublic();
        // Give this contract some ether to make winnersPot meaningful
        vm.deal(address(this), 1 ether);
        // Send some ether to the contract so address(this).balance > 0
        (bool success, ) = address(c).call{value: 0.5 ether}("");
        require(success, "transfer failed");

        // Call AdjustBetAmounts with fuzzed value
        c.AdjustBetAmounts(newBetLimit);

        // After AdjustBetAmounts, winnersPot() must equal half the contract's balance
        uint256 halfBalance = address(c).balance / 2;
        assertTrue(c.winnersPot() == halfBalance, "winnersPot() should equal half of contract balance");
    }
}

