pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newLimit) public {
        vm.assume(newLimit > 0 && newLimit <= type(uint256).max / 2);
        c.OpenToThePublic();
        c.AdjustBetAmounts(newLimit);
        uint256 expected = address(c).balance / 2;
        uint256 actual = c.winnersPot();
        assertTrue(actual == expected, "winnersPot() should return half of contract balance");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 amount, uint256 fundAmount) public {
        fundAmount = bound(fundAmount, 1, type(uint128).max);
        vm.assume(amount > 0);

        c.OpenToThePublic();
        address(c).call{value: fundAmount}("");

        c.AdjustBetAmounts(amount);

        uint256 balance = address(c).balance;
        uint256 pot = c.winnersPot();
        assertTrue(pot == balance / 2, "winnersPot() should equal half the balance");
    }
}
